#!/usr/bin/env python3
"""Dylan Crow, with Anthropic Claude assistance; Apache-2.0.
usage: checkword.py WORD.json.gz PRICING_DIR
Independent checker for 'bitE8/1' bit words (no import of the design/compile code).
Checks: (1) labels are the 120 root lines of an even unimodular rank-8 lattice (E8);
(2) frame legality: every register's frames nested (exact rational ranks), every gate at one common frame,
    retained totals present and y at frame 0 at the scatter, start/final frames as required;
(3) exact F2 semantics on all 2v+R columns (x, y, helper dirt): y_t += x_t, x and helpers restored;
(4) Gram determinants of every frame basis (nondegeneracy) and their prime factors;
(5) five-stage price: histogram, deficit, exact moment root (repo's moment.certify, with and without
    the inherited 1e-16 bad envelope)."""
import sys, json, gzip, math
from fractions import Fraction as Fr
from collections import Counter
def load(p):
    with (gzip.open(p,'rt') if p.endswith('.gz') else open(p)) as f: return json.load(f)
c=load(sys.argv[1])
v,h,R=c['v'],c['h'],c['R']; nreg=2*v+R
lines=[tuple(x) for x in c['lines']]
den=2 if c['form']=='<x,y>/2' else 4
def ip(a,b):
    s=sum(x*y for x,y in zip(a,b)); assert s%den==0; return s//den
# (1) labels
assert len(lines)==v==120 and h==8
assert all(ip(a,a)==2 for a in lines)
assert all(abs(ip(lines[i],lines[j]))<=1 for i in range(v) for j in range(i+1,v)), 'not distinct root lines'
def rank(vecs):
    rows=[[Fr(x) for x in r] for r in vecs]; rk=0; n=len(rows[0]) if rows else 0
    for col in range(n):
        p=next((i for i in range(rk,len(rows)) if rows[i][col]!=0),None)
        if p is None: continue
        rows[rk],rows[p]=rows[p],rows[rk]
        for i in range(len(rows)):
            if i!=rk and rows[i][col]!=0:
                f=rows[i][col]/rows[rk][col]; rows[i]=[a-f*b for a,b in zip(rows[i],rows[rk])]
        rk+=1
    return rk
def basis(idx):
    B=[]
    for i in idx:
        if rank([lines[j] for j in B]+[lines[i]])>len(B): B.append(i)
    return B
def det(M):
    M=[[Fr(x) for x in r] for r in M]; n=len(M); d=Fr(1)
    for col in range(n):
        p=next((i for i in range(col,n) if M[i][col]!=0),None)
        if p is None: return Fr(0)
        if p!=col: M[col],M[p]=M[p],M[col]; d=-d
        d*=M[col][col]
        for i in range(col+1,n):
            f=M[i][col]/M[col][col]; M[i]=[a-f*b for a,b in zip(M[i],M[col])]
    return d
full=basis(range(v)); assert len(full)==8
G8=det([[ip(lines[a],lines[b]) for b in full] for a in full])
# lattice generated by roots: unimodular check via a Z-basis is heavier; we check det of Gram of an integral basis
# found greedily among roots whose Gram has det 1 (exists for E8)
import itertools
print('labels: 120 distinct lines of norm 2 (pairwise |ip| <= 1), spanning rank 8')
# (2) frames
fr=c['frames']
fb=[basis(f) for f in fr]
fdim=[len(b) for b in fb]
assert fdim[c['start'][v]]==0
FULLID=[i for i,d in enumerate(fdim) if d==8]
def inside(a,b):
    if fdim[a]>fdim[b]: return False
    return rank([lines[j] for j in fb[a]+fb[b]])==fdim[b]
cache={}
def nested(a,b):
    k=(a,b)
    if k not in cache: cache[k]=inside(a,b)
    return cache[k]
cur=list(c['start']); steps=[[] for _ in range(nreg)]
for r in range(v): assert fdim[cur[r]]==1 and rank([lines[r]]+[lines[j] for j in fb[cur[r]]])==1, 'x start is its line'
for r in range(v,nreg): assert fdim[cur[r]]==0
def climb(r,f):
    if cur[r]==f: return
    assert nested(cur[r],f) and fdim[cur[r]]<fdim[f], ('frame not nested',r,cur[r],f)
    steps[r].append(fdim[f]-fdim[cur[r]]); cur[r]=f
val=[1<<i for i in range(nreg)]   # column i: x_i (i<v), y0 (v..2v-1), dirt of helper (2v..)
def run(gates,tag):
    for k,(f,d,srcs) in enumerate(gates):
        regs=[d]+srcs
        assert len(set(regs))==len(regs) and all(0<=x<nreg for x in regs),(tag,k)
        assert all(x>=v for x in [d]), ('x register written',tag,k)   # x registers are never destinations
        for x in regs: climb(x,f)
        for s in srcs: val[d]^=val[s]
run(c['D'],'D')
assert all(fdim[cur[r]]==0 for r in range(v,nreg)),'dirt compensation must be at frame 0'
run(c['A'],'A')
# scatter
ret=c['ret']; cent_rank=[]
for q in ret: assert q>=2*v; cent_rank.append(fdim[cur[q]])
assert all(fdim[cur[v+t]]==0 for t in range(v)),'y left frame 0 before the scatter'
copies=[val[q] for q in ret]
for t,row in enumerate(c['scatter']):
    for k in row: val[v+t]^=copies[k]
run(c['B'],'B')
run(c['C'],'C')
for r in range(nreg): climb(r,c['final'][r])
for r in range(v): assert fdim[c['final'][r]]==8
for t in range(v):
    f=c['final'][v+t]; assert fdim[f]==7
    assert all(ip(lines[t],lines[j])==0 for j in fb[f]),'y final frame is the cap of its label'
for r in range(2*v,nreg): assert fdim[c['final'][r]]==8
# (3) F2 semantics
for s in range(v): assert val[s]==1<<s
for t in range(v): assert val[v+t]==(1<<(v+t))|(1<<t),('target',t)
for r in range(2*v,nreg): assert val[r]==1<<r,('helper not restored',r)
print('legality + exact F2 on all %d columns: PASS (gates D/A/B/C = %d/%d/%d/%d)'%(nreg,len(c['D']),len(c['A']),len(c['B']),len(c['C'])))
# (4) nondegeneracy
used=set(c['start'])|set(c['final'])|{f for g in c['D']+c['A']+c['B']+c['C'] for f in [g[0]]}
primes=Counter(); dets={}
def factor(n):
    n=abs(n); out=Counter(); p=2
    while p*p<=n:
        while n%p==0: out[p]+=1; n//=p
        p+=1
    if n>1: out[n]+=1
    return out
for f in used:
    if fdim[f]==0: continue
    B=fb[f]; d=det([[ip(lines[a],lines[b]) for b in B] for a in B])
    assert d>0
    dets[f]=d
    for p in factor(d.numerator): primes[p]+=1
print('nondegeneracy: %d used frames, all Gram dets > 0 (positive-definite form); primes in dets:'%len(dets),sorted(primes))
# (5) price
H=Counter()
for r in range(nreg):
    for s in steps[r]: H[s]+=5
for rk in cent_rank: H[rk]+=5
for rr in (2*h-2,h-1,2*h+2,4): H[rr]+=2*v
m=5*h; W=4*v+R
mass=sum(r*n for r,n in H.items())
L=sum(cent_rank)
print('histogram',dict(sorted(H.items())),'m',m,'W',W,'mass',mass,'deficit',m*W-mass,'(4v-5L =',4*v-5*L,')','maxchild',max(H))
assert m*W-mass==4*v-5*L and 2*max(H)<m
sys.path.insert(0,sys.argv[2])
import moment
for bad in (False,True):
    r=moment.certify(H,m,W,bad)
    print('bad envelope' if bad else 'no envelope ','saving in [%s, %s]'%(r['lower'][:22],r['upper'][:22]))
